import React from 'react';

const SkeletonCard = () => {
  return (
    <div className="col-md-6 col-lg-4 mb-4">
      <div className="card h-100" aria-hidden="true">
        <div className="card-img-top" style={{ height: '220px', backgroundColor: 'rgba(255,255,255,0.1)' }}></div>
        <div className="card-body placeholder-glow">
          <h5 className="card-title">
            <span className="placeholder col-8"></span>
          </h5>
          <p className="card-text">
            <span className="placeholder col-7"></span>
            <span className="placeholder col-4"></span>
          </p>
        </div>
        <div className="card-footer placeholder-glow d-flex justify-content-between">
            <span className="placeholder col-3"></span>
            <span className="placeholder col-4"></span>
        </div>
      </div>
    </div>
  );
};

export default SkeletonCard;
